// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint256 _basefee, uint64 _number, uint64 _timestamp, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        uint64 number = _number;
        uint64 timestamp = _timestamp;
        bytes32 hash = _hash;
        uint64 sequenceNumber = _sequenceNumber;
        bytes32 batcherHash = _batcherHash;
        uint256 l1FeeOverhead = _l1FeeOverhead;
        uint256 l1FeeScalar = _l1FeeScalar;

        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(number, timestamp, _basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar);

        assertTrue(c.basefee() == _basefee);
    }
}
